import 'dart:convert';

import '../../core/app_exception.dart';
import '../../core/env.dart';
import '../../core/result.dart';
import '../../data/models/user_model.dart';

/// Envelope written into / read out of QR codes. The signature gate means
/// only QR codes generated by this app are accepted by the scanner — any
/// other QR code falls through to a friendly "not a Bingo QR" error.
class QrPayload {
  const QrPayload({
    required this.uid,
    required this.name,
    this.linkedinUrl,
  });

  factory QrPayload.fromUser(UserModel user) => QrPayload(
        uid: user.id,
        name: user.name,
        linkedinUrl: user.linkedinUrl,
      );

  final String uid;
  final String name;
  final String? linkedinUrl;

  static const _appId = 'namma_bingo_app';
  static const _type = 'bingo_user';

  /// Base64url-encoded JSON envelope. Base64url avoids the QR-unfriendly
  /// `+` / `/` characters in standard base64, which keeps the encoded
  /// payload alphanumeric and helps scanners on noisier displays.
  ///
  /// The payload is intentionally minimal — fewer characters means a less
  /// dense QR, which means more forgiving scans at distance and on low-end
  /// cameras. Any field not validated by [decode] is omitted.
  String encode() {
    final json = {
      'app': _appId,
      'signature': Env.qrSignature,
      'type': _type,
      'uid': uid,
      'name': name,
      if (linkedinUrl != null && linkedinUrl!.isNotEmpty)
        'linkedinUrl': linkedinUrl,
    };
    return base64UrlEncode(utf8.encode(jsonEncode(json)));
  }

  static Result<QrPayload> decode(String raw) {
    try {
      String decoded;
      try {
        decoded = utf8.decode(base64Url.decode(_pad(raw)));
      } catch (_) {
        // Fallback: maybe the payload was emitted as plain JSON.
        decoded = raw;
      }

      final parsed = jsonDecode(decoded);
      if (parsed is! Map<String, dynamic>) {
        return const Result.err(ValidationException('QR is not a valid envelope'));
      }
      if (parsed['app'] != _appId ||
          parsed['type'] != _type ||
          parsed['signature'] != Env.qrSignature) {
        return const Result.err(
          ValidationException("This QR isn't from Namma Bingo."),
        );
      }
      final uid = parsed['uid'] as String?;
      final name = parsed['name'] as String?;
      if (uid == null || uid.isEmpty || name == null || name.isEmpty) {
        return const Result.err(
          ValidationException('QR is missing required fields'),
        );
      }
      return Result.ok(QrPayload(
        uid: uid,
        name: name,
        linkedinUrl: parsed['linkedinUrl'] as String?,
      ));
    } catch (e, st) {
      return Result.err(
        ValidationException('Could not read QR', cause: e, stackTrace: st),
      );
    }
  }

  /// Base64url decode is strict about padding; pad if needed.
  static String _pad(String s) {
    final remainder = s.length % 4;
    if (remainder == 0) return s;
    return s.padRight(s.length + (4 - remainder), '=');
  }
}
